let lang = 'es';
try { const saved = localStorage.getItem('vs-language'); if(saved==='es'||saved==='en') lang=saved; } catch {}
let filter='all';
let metric='ore';
let activeProject=null;
const metrics={ore:{plan:1000,unit:'t',ratios:[.94,1.06,.97,1.12,1.03,.99]},drilling:{plan:250,unit:'m',ratios:[1.04,.95,1.08,1.02,.91,1.05]},development:{plan:30,unit:'m',ratios:[.88,.98,1.12,1.05,1.03,.94]}};
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];

function projectVisual(p){
 const t=translations[lang];
 let inner='';
 if(p.id==='mining')inner=`<div class="mini-report"><div class="mini-report-top"><span>${t.reportTitle}</span><span>↗</span></div><div class="mini-stats">${t.reportLabels.map((s,i)=>`<div class="mini-stat"><span>${s}</span><strong>${t.reportStats[i]}</strong></div>`).join('')}</div><div class="mini-graph">${[37,55,49,66,60,82,73,92,84].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></div>`;
 if(p.id==='supply')inner=`<div class="supply-visual"><div class="process-line"></div><div class="supply-flow">${t.supplyLabels.map((s,i)=>`<span><i>${['↗','✓','≡','↗'][i]}</i>${s}</span>`).join('')}</div><div class="supply-summary"><span>${t.supplySummary}</span><i></i></div></div>`;
 if(p.id==='ai')inner=`<div class="ai-visual"><svg viewBox="0 0 300 180" fill="none" aria-hidden="true"><g stroke="#8297ad" stroke-opacity=".6"><path d="M40 40L144 25L254 90M40 40L144 90L254 90M40 140L144 90M40 140L144 155L254 90M40 90L144 25M40 90L144 90M40 90L144 155"/></g><g fill="#f1f4f4" stroke="#7790a2"><circle cx="40" cy="40" r="12"/><circle cx="40" cy="90" r="12"/><circle cx="40" cy="140" r="12"/><circle cx="144" cy="25" r="16"/><circle cx="144" cy="90" r="16"/><circle cx="144" cy="155" r="16"/></g><circle cx="254" cy="90" r="25" fill="#2b4b61"/><path d="M246 90L252 96L263 83" stroke="#f0f5f6" stroke-width="1.5"/><circle cx="144" cy="90" r="5" fill="#b17c59"/><g fill="#6e8294" font-family="Arial,sans-serif" font-size="7" letter-spacing="1"><text x="25" y="178">${t.aiLabels[0]}</text><text x="124" y="178">${t.aiLabels[1]}</text><text x="234" y="140">${t.aiLabels[2]}</text></g></svg></div>`;
 return `<div class="project-visual ${p.id}"><span class="visual-label">${['MINING INTELLIGENCE','SUPPLY CHAIN ANALYTICS','APPLIED BUSINESS ANALYTICS'][projects.indexOf(p)]}</span>${inner}<span class="project-number">0${projects.indexOf(p)+1} /</span><span class="project-open" aria-hidden="true">↗</span></div>`;
}

function renderProjects(){
 const t=translations[lang];
 $('#project-grid').innerHTML=projects.map(p=>`<article class="project-card" ${filter!=='all'&&filter!==p.category?'hidden':''}><button type="button" data-project="${p.id}" aria-label="${t.viewProject}: ${p[lang].title}">${projectVisual(p)}<div class="project-body"><span class="project-category">${p[lang].eyebrow}</span><h3>${p[lang].title}</h3><p>${p[lang].summary}</p><div class="project-tags">${p.tags.map(s=>`<span>${s}</span>`).join('')}</div></div></button></article>`).join('');
 $$('[data-project]').forEach(b=>b.addEventListener('click',()=>openProject(b.dataset.project)));
}

function renderDialog(){
 const p=projects.find(p=>p.id===activeProject);
 if(!p)return;
 const t=translations[lang],c=p[lang];
 $('#dialog-category').textContent=c.eyebrow;
 $('#dialog-content').innerHTML=`<h2 id="dialog-title">${c.title}</h2><p class="dialog-summary">${c.summary}</p>${c.details.map((d,i)=>`<div class="detail-row"><h3>${t.detailLabels[i]}</h3><p>${d}</p></div>`).join('')}<div class="dialog-tags">${p.tags.map(s=>`<span>${s}</span>`).join('')}</div><p class="dialog-note">${t.detailNote}</p><a class="dialog-contact" href="mailto:victoriasanchezrudati@gmail.com"><span>${t.detailCta}</span><span aria-hidden="true">↗</span></a>`;
}

function openProject(id){activeProject=id;renderDialog();$('#project-dialog').showModal();document.body.classList.add('dialog-open');}
function closeProject(){$('#project-dialog').close();}
$('#close-dialog').addEventListener('click',closeProject);
$('#project-dialog').addEventListener('close',()=>{document.body.classList.remove('dialog-open');activeProject=null;});
$('#project-dialog').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProject();});

function formatNumber(value){return new Intl.NumberFormat(lang==='es'?'es-AR':'en-US',{maximumFractionDigits:1}).format(value);}
function updateDemo(){
 const t=translations[lang],m=metrics[metric],ratio=Number($('#result-range').value),actual=Math.round(m.plan*ratio/100*10)/10,diff=Math.round((actual-m.plan)*10)/10;
 $('#actual-value').textContent=formatNumber(actual);$('#unit').textContent=m.unit;$('#plan-value').textContent=`${formatNumber(m.plan)} ${m.unit}`;$('#performance').textContent=`${ratio}%`;$('#status-label').textContent=ratio>=100?t.planMet:t.belowPlan;
 $('.status-line').classList.toggle('below',ratio<100);$('#slider-value').textContent=`${ratio}% ${t.ofPlan}`;$('#result-range').setAttribute('aria-valuetext',`${formatNumber(actual)} ${m.unit}, ${ratio}% ${t.ofPlan}`);
 $('#demo-insight').textContent=diff>0?t.aboveInsight(formatNumber(diff),m.unit):diff<0?t.belowInsight(formatNumber(-diff),m.unit):t.equalInsight;
 const ratios=[...m.ratios,ratio/100];
 $('#bar-chart').innerHTML=ratios.map((r,i)=>`<div class="bar-group"><i class="bar plan-bar" style="height:${100/1.4}%"></i><i class="bar actual-bar" style="height:${r/1.4*100}%"></i><span>${t.days[i]}</span></div>`).join('');
 $('#bar-chart').setAttribute('aria-label',`${t.chartAria}. ${t.planLegend}: ${formatNumber(m.plan)} ${m.unit}. ${t.actualLabel}: ${formatNumber(actual)} ${m.unit}, ${ratio}% ${t.ofPlan}.`);
 $$('[data-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.metric===metric)));
}

function setLanguage(next){
 lang=next;const t=translations[lang];
 document.documentElement.lang=lang;document.title=t.title;document.querySelector('meta[name="description"]').content=t.description;
 $$('[data-i18n]').forEach(el=>{if(t[el.dataset.i18n]!==undefined)el.innerHTML=t[el.dataset.i18n];});
 $$('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t[el.dataset.i18nAria]));
 $$('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));
 $('#copy-status').textContent='';renderProjects();updateDemo();if(activeProject)renderDialog();
 try{localStorage.setItem('vs-language',lang);}catch{}
}

$$('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderProjects();}));
$$('[data-metric]').forEach(b=>b.addEventListener('click',()=>{metric=b.dataset.metric;updateDemo();}));
$('#result-range').addEventListener('input',updateDemo);
$('.menu-toggle').addEventListener('click',()=>{const expanded=$('.menu-toggle').getAttribute('aria-expanded')==='true';$('.menu-toggle').setAttribute('aria-expanded',String(!expanded));$('#mobile-nav').hidden=expanded;});
$$('#mobile-nav a').forEach(a=>a.addEventListener('click',()=>{$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('click',e=>{if(!e.target.closest('.site-header')){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
$('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('victoriasanchezrudati@gmail.com');$('#copy-status').textContent=translations[lang].copied;}catch{$('#copy-status').textContent=translations[lang].copyFailed;}});
setLanguage(lang);
